import{_ as t,o as a,c as o,a2 as n}from"./chunks/framework.CXsxtpvq.js";const s="/asset-studio/shots/en/09-settings.webp",m=JSON.parse('{"title":"Settings","description":"","frontmatter":{},"headers":[],"relativePath":"guide/settings.md","filePath":"guide/settings.md"}'),r={name:"guide/settings.md"};function i(l,e,d,h,g,u){return a(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h1><p>Everything is changed on the <strong>Settings</strong> page and stored on the server in <code>data/settings/</code>, so every browser on the PC sees the same settings.</p><p><img src="'+s+'" alt="Settings"></p><h2 id="general" tabindex="-1">General <a class="header-anchor" href="#general" aria-label="Permalink to &quot;General&quot;">​</a></h2><ul><li><strong>Language</strong>: 한국어, English, 日本語, 简体中文. &quot;Follow the browser&quot; is the default.</li><li><strong>Theme</strong>: light, dark or follow the system.</li><li><strong>Danbooru tag autocomplete</strong>: turns autocomplete in prompt fields on or off.</li></ul><h2 id="connection-·-comfyui-connection" tabindex="-1">Connection · ComfyUI connection <a class="header-anchor" href="#connection-·-comfyui-connection" aria-label="Permalink to &quot;Connection · ComfyUI connection&quot;">​</a></h2><ul><li><strong>Connection</strong>: shows the ComfyUI version, Python, GPU and the running and queued jobs.</li><li><strong>Local ComfyUI address</strong>: default <code>http://127.0.0.1:8188</code>.</li><li><strong>Find automatically</strong>: lists the ComfyUI installs on this PC (the running one, Stability Matrix, portable, git). <strong>Use this install</strong> fills in the fields; check them and press <strong>Save settings</strong>.</li><li>With the <strong>ComfyUI folder</strong> and <strong>Python executable</strong> filled in, this page can <strong>start</strong>, <strong>stop</strong> and <strong>restart</strong> ComfyUI. While images are being generated, stop and restart wait for the current job. A ComfyUI started elsewhere shows as an &quot;external process&quot; and cannot be stopped here.</li></ul><h2 id="danbooru-tag-data" tabindex="-1">Danbooru tag data <a class="header-anchor" href="#danbooru-tag-data" aria-label="Permalink to &quot;Danbooru tag data&quot;">​</a></h2><p>Where the tag files for autocomplete and tag checks are. They are found automatically when ComfyUI-EasyUseAnima is installed.</p><h2 id="lora-training" tabindex="-1">LoRA training <a class="header-anchor" href="#lora-training" aria-label="Permalink to &quot;LoRA training&quot;">​</a></h2><p>The trainer (anima_lora) folder and its Python, the folder trained LoRAs are copied to, and the model files to train on (official Anima base, generation model). Each path shows whether the file was found. For installing the trainer, see the <a href="https://github.com/kiritype/asset-studio#lora-training" target="_blank" rel="noreferrer">README&#39;s LoRA training</a>.</p><p><strong>Find in ComfyUI</strong> fills the LoRA output folder with a LoRA folder ComfyUI uses (its <code>anima</code> subfolder when there is one).</p><p>ComfyUI custom nodes are installed at the tested versions by <code>tools/install_comfy_nodes.py</code>; see the <a href="https://github.com/kiritype/asset-studio#install" target="_blank" rel="noreferrer">README&#39;s Install</a>.</p><h2 id="gpu-use-·-gpu-wait-rules" tabindex="-1">GPU use · GPU wait rules <a class="header-anchor" href="#gpu-use-·-gpu-wait-rules" aria-label="Permalink to &quot;GPU use · GPU wait rules&quot;">​</a></h2><p>Asset Studio takes turns so that generation, tagging, post-processing, LoRA training and VLM review never use the GPU at the same time.</p><ul><li><strong>GPU use</strong>: shows who is using the GPU. A reservation left by an outside program can be released here.</li><li><strong>GPU wait rules</strong>: for each kind of work, how much free GPU memory is needed before it starts, and which programs make it wait while they run. Useful when you game or use other generation tools at the same time.</li></ul><h2 id="vlm-server-·-vlm-review-optional" tabindex="-1">VLM server · VLM review (optional) <a class="header-anchor" href="#vlm-server-·-vlm-review-optional" aria-label="Permalink to &quot;VLM server · VLM review (optional)&quot;">​</a></h2><p>With a local vision-language model server (for example LM Studio), generated images get an automatic advisory verdict. It is off by default.</p><ul><li><strong>VLM server</strong>: address, model and the commands that load and unload the model.</li><li><strong>Use VLM review</strong>: shows VLM verdicts in the gallery and regenerates failed images with a new seed up to <strong>Max automatic regenerations</strong> times.</li><li>People always make the final call; the VLM verdict is advisory.</li></ul>',19)])])}const f=t(r,[["render",i]]);export{m as __pageData,f as default};
